import re
files = ['apps-build.html', 'storefronts.html', 'agents.html', 'support.html']
for f in files:
    with open(f, 'r') as fh:
        lines = fh.readlines()
    # Find nav-links section and print lines with self-link
    basename = f.replace('.html', '')
    in_nav = False
    for i, line in enumerate(lines):
        if 'nav-links' in line:
            in_nav = True
        if in_nav:
            if basename in line and 'href' in line:
                print(f'{f} line {i+1}: {line.strip()}')
            if '</ul>' in line:
                in_nav = False
"
